"minimum":-1000000,"maximum":1000000},"width":{"type":"number","minimum":-1000000,"maximum":1000000},"height":{"type":"number","minimum":-1000000,"maximum":1000000},"targetY":{"type":"number","minimum":-1000000,"maximum":1000000},"targetWidth":{"type":"number","minimum":-1000000,"maximum":1000000},"targetHeight":{"type":"number","minimum":-1000000,"maximum":1000000}},"additionalProperties":false},"addObjects":{"type":"array","items":{"oneOf":[{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z][a-zA-Z0-9_-]{0,99}$"},"kind":{"const":"point"},"position":{"type":"array","items":{"type":"number"},"minItems":2,"maxItems":2},"draggable":{"type":"boolean"}},"required":["id","kind","position","draggable"],"additionalProperties":false},{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z][a-zA-Z0-9_-]{0,99}$"},"kind":{"const":"polygon"},"vertexIds":{"type":"array","items":{"type":"string","pattern":"^[a-zA-Z][a-zA-Z0-9_-]{0,99}$"},"minItems":3,"maxItems":100}},"required":["id","kind","vertexIds"],"additionalProperties":false},{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z][a-zA-Z0-9_-]{0,99}$"},"kind":{"const":"angle_token"},"sourceVertexId":{"type":"string","pattern":"^[a-zA-Z][a-zA-Z0-9_-]{0,99}$"}},"required":["id","kind","sourceVertexId"],"additionalProperties":false},{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z][a-zA-Z0-9_-]{0,99}$"},"kind":{"const":"prism"},"dimensions":{"type":"array","items":{"type":"number","exclusiveMinimum":0,"maximum":10000},"minItems":3,"maxItems":3}},"required":["id","kind","dimensions"],"additionalProperties":false},{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z][a-zA-Z0-9_-]{0,99}$"},"kind":{"const":"math_model"},"model":{"enum":["number_line","fraction_bar","linear_balance","quadratic_graph","percentage_grid","ratio_table","coordinate_plane","rectangle_area","pythagorean","linear_graph"]},"parameters":{"type":"object","properties":{"x":{"type":"number","minimum":-1000000,"maximum":1000000},"a":{"type":"number","minimum":-1000000,"maximum":1000000},"b":{"type":"number","minimum":-1000000,"maximum":1000000},"c":{"type":"number","minimum":-1000000,"maximum":1000000},"numerator":{"type":"number","minimum":-1000000,"maximum":1000000},"denominator":{"type":"number","minimum":-1000000,"maximum":1000000},"targetX":{"type":"number","minimum":-1000000,"maximum":1000000},"targetRatio":{"type":"number","minimum":-1000000,"maximum":1000000},"targetA":{"type":"number","minimum":-1000000,"maximum":1000000},"targetB":{"type":"number","minimum":-1000000,"maximum":1000000},"targetC":{"type":"number","minimum":-1000000,"maximum":1000000},"y":{"type":"number","minimum":-1000000,"maximum":1000000},"width":{"type":"number","minimum":-1000000,"maximum":1000000},"height":{"type":"number","minimum":-1000000,"maximum":1000000},"targetY":{"type":"number","minimum":-1000000,"maximum":1000000},"targetWidth":{"type":"number","minimum":-1000000,"maximum":1000000},"targetHeight":{"type":"number","minimum":-1000000,"maximum":1000000}},"required":[],"additionalProperties":false}},"required":["id","kind","model","parameters"],"additionalProperties":false}]},"minItems":0,"maxItems":100}},"required":[],"additionalProperties":false},"successCriteria":{"$ref":"#/$defs/criterion"},"hints":{"type":"array","items":{"type":"string","minLength":1,"maxLength":2000},"minItems":0,"maxItems":100},"feedback":{"type":"object","properties":{"success":{"type":"string","minLength":1,"maxLength":2000}},"required":["success"],"additionalProperties":false}},"required":["id","order","instruction","allowedInteractions","scenePatch","successCriteria","hints","feedback"],"additionalProperties":false},"minItems":1,"maxItems":100},"completion":{"type":"object","properties":{"requiredCheckpointIds":{"type":"array","items":{"type":"string","pattern":"^[a-zA-Z][a-zA-Z0-9_-]{0,99}$"},"minItems":1,"maxItems":100,"uniqueItems":true}},"required":["requiredCheckpointIds"],"additionalProperties":false},"recognition":{"type":"array","minItems":1,"maxItems":100,"items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":2000},"mode":{"enum":["tap","drag","formula"]},"choices":{"type":"array","minItems":2,"maxItems":8,"items":{"type":"string","minLength":1,"maxLength":2000}},"correct":{"type":"integer","minimum":1,"maximum":8},"explanation":{"type":"string","minLength":1,"maxLength":2000},"hint":{"type":"string","minLength":1,"maxLength":2000},"diagram":{"enum":["none","triangle","circle","cone","chart"]},"uime":{"type":"object","properties":{"kind":{"enum":["TOKEN_CLASSIFIER","TAP_COEFFICIENT","NUMBER_LINE_SELECTOR","INEQUALITY_SIGN_SWITCH","FORMULA_SNAP_BUILDER","PARABOLA_SLIDER","DELTA_STATE_TOGGLE","TRIANGLE_HOTSPOT_TAP","GEOMETRIC_HOTSPOT_FINDER","ANGLE_MEASURE_TAP","3D_SOLID_INSPECTOR","CHART_BAR_TAP","EVENT_CARD_BUCKET"]},"labels":{"type":"array","items":{"type":"string","minLength":1,"maxLength":2000},"minItems":0,"maxItems":100},"tokens":{"type":"array","items":{"type":"string","minLength":1,"maxLength":2000},"minItems":0,"maxItems":100},"answers":{"type":"array","minItems":1,"maxItems":8,"items":{"type":"number"}},"min":{"type":"number"},"max":{"type":"number"},"step":{"type":"number","exclusiveMinimum":0},"solid":{"enum":["cone","cylinder","sphere"]},"hotspots":{"type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":2000},"x":{"type":"number","minimum":0,"maximum":360},"y":{"type":"number","minimum":0,"maximum":240},"width":{"type":"number","minimum":1,"maximum":360},"height":{"type":"number","minimum":1,"maximum":240}},"required":["label","x","y","width","height"],"additionalProperties":false},"minItems":0,"maxItems":100},"svg":{"type":"string","maxLength":65536}},"required":["kind","labels","tokens","answers","min","max","step","solid","hotspots"],"additionalProperties":false}},"required":["question","mode","choices","corr